    // 2. Lookahead Synergy:
    // Focus on "fit-for-next" optimization.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward potential to fit the next item perfectly.
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Penalize creating a blockage that forces a new bin for the next item.
            score += (next_item_size - post_residual) as f64 * 1.2;
        }
    }

    // 3. Adaptive Bin Pressure:
    if is_new_bin {
        // Only open new bins if existing bins are highly fragmented (low mean_residual).
        // Otherwise, enforce aggressive packing into existing bins.
        let dynamic_penalty = 55.0 + (progress * 25.0);
        score += if mean_residual < 18.0 { 
            dynamic_penalty * 0.4 
        } else { 
            dynamic_penalty 
        };
    } else {
        // Prioritize using bins where we have few options (fitting_bins_count).
        if fitting_bins_count == 1 {
            score -= 65.0;
        }
        // Penalize excessive open bin sprawl.
        score += (open_bins_count as f64) * 0.8;
    }

    // 4. Perfect Fit Reward:
    if post_residual == 0 {
        score -= 25.0;
    }

