pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Enhanced non-linear penalty: Use a steeper curve for larger residuals to prioritize tight packing
    let mut score = (post_residual as f64).powf(1.42);

    // 1. Predictive Lookahead:
    // Reward exact matches to next_item_size and penalize gaps that block future fits
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 142.0; 
        } else if post_residual > next_item_size {
            score += (post_residual as f64 - next_item_size as f64).powf(0.82) * 0.68;
        } else {
            // Stronger penalty for stranding gaps that prevent fitting the next item
            score += (next_item_size - post_residual) as f64 * 9.4;
        }
    }

    // 2. Adaptive New-Bin Thresholding:
    // Tighten new bin creation logic using a dynamic threshold based on density
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let threshold = 12.5 + (open_bins_count as f64 * 0.08) - (progress * 6.0);
        if mean_residual < threshold {
            score -= 35.0; 
        } else {
            score += 260.0; // Increased cost for opening a new bin
        }
    } else {
        // 3. Density Balancing:
        // Reward perfect fills and very small residuals aggressively
        if post_residual == 0 {
            score -= 125.0;
        } else if post_residual < 8 {
            score -= 85.0 - (post_residual as f64 * 7.5);
        }
    }

    // 4. Fitting Pressure:
    // If only one bin fits, force it to avoid fragmentation
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 450.0;
    }

    // 5. Harmonic Alignment:
    // Prioritize residuals that leave "clean" room for standard item sizes
    if post_residual % 25 == 0 {
        score -= 55.0;
    } else if post_residual % 12 == 0 {
        score -= 22.0;
    }

    // 6. Terminal Phase: 
    // Aggressive consolidation in the final 12% of the stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.88 {
        if bin_residual == bin_capacity {
            score += 950.0; 
        }
    }

    // 7. Global State Normalization:
    // Penalize high open bin count relative to total items processed
    score += (open_bins_count as f64 / (total_items as f64 / 500.0 + 1.0)) * 6.5;

    // 8. Mean Residual Correction:
    // Penalize deviation to keep packing uniform across all active bins
    if bin_residual != bin_capacity {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.85;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" bins (post_residual between 1 and 9)
    // Small residuals are hard to fill with items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead: Reward bins that can accommodate the next item perfectly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for a "Best Fit" scenario regarding the next item
            let delta = (post_residual - next_item_size) as f64;
            score -= (100.0 - delta) * 0.5;
        } else {
            // Penalize if this placement prevents the next item from fitting in this bin
            score += 20.0;
        }
    }

    // 3. Pressure management: Use existing bins before opening new ones
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current fit is terrible (high residual)
        // or if we have very few open bins (avoiding fragmentation).
        score += 45.0 - (open_bins_count as f64 * 0.5);
    } else {
        // Favor bins that align with the global average residual to keep bins balanced
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // 4. Critical threshold: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 5. Progression: As the stream nears the end, be more conservative with space
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}
